"""Saved-array verification and complete old/new ledger; no new simulation."""
from pathlib import Path
import json,numpy as np
from run_motor_threshold_minus2 import O,TARGET,BASE,sha,dump

def main():
 h=json.loads((O/'PREREGISTRATION.json').read_text())['source_hashes'];assert all(sha(Path(p))==v for p,v in h.items());bm=json.loads((BASE/'MANIFEST_SHA256.json').read_text());assert all(sha(BASE/('normal/'+f))==bm['normal/'+f] for f in ['BODY.npz','INTERVALS.npz','RECORDS.json','CONTACTS.json']);tm=TARGET.parent/'MANIFEST_SHA256.json';assert sha(TARGET)==json.loads(tm.read_text())['TARGETS.json']
 z=np.load(O/'ALL_NODE_TICK_EVENTS.npz');iv=np.load(O/'INTERVALS.npz');sp=z['spikes'];np.testing.assert_array_equal(sp.reshape(50,10,12000).sum(1),iv['spikes']);changes=json.loads((O/'THRESHOLD_CHANGES_29.json').read_text());nodes=json.loads(TARGET.read_text())['unique_local_nodes'];assert [r['local_node'] for r in changes]==nodes and all(r['old_mV']==-50 and r['new_mV']==-52 for r in changes)
 source=Path('/run/media/sensen/Data2/cell_wound_prototype/engine/neural_cond.py');new=source.read_text();old=new.replace("    def __init__(self, n_neurons, params=None, dt_ms=0.1, voltage_method='backward_euler',\n                 threshold_offset_mV=None):","    def __init__(self, n_neurons, params=None, dt_ms=0.1, voltage_method='backward_euler'):").replace("        offset = np.zeros(self.n) if threshold_offset_mV is None else np.asarray(threshold_offset_mV, float)\n        if offset.shape != (self.n,) or not np.isfinite(offset).all():\n            raise ValueError('threshold_offset_mV must be a finite per-neuron vector')\n        if np.any(self.p.reset_mV >= self.p.threshold_mV + offset):\n            raise ValueError('effective threshold must remain above reset')\n        self.threshold_offset_mV = offset.copy()\n        self.threshold_offset_mV.flags.writeable = False\n",'').replace('p.threshold_mV + self.threshold_offset_mV','p.threshold_mV');import hashlib
 oldsha=hashlib.sha256(old.encode()).hexdigest();assert oldsha=='f4e6d5af5473a187f3da521273e606d726bd5df6272df214457e14e9aa289499';(O/'neural_cond_before.py').write_text(old);(O/'neural_cond_after.py').write_text(new);dump(O/'CHANGE_LEDGER.json',dict(path=str(source),old_sha256=oldsha,new_sha256=sha(source),only_behavioral_addition='optional per-neuron offset at comparison, default zero; adaptation current unchanged',inputs_old_new={p:{'old':v,'new':sha(Path(p))} for p,v in h.items()}));dump(O/'VERIFICATION.json',dict(exit_code=0,all500_ticks_12000nodes_exact_to_new_window_counts=True,target_nodes_fixed29=True,old_source_reconstructed_sha_exact=True,historical_inputs_unchanged=True,models=0,forward=0,body_step=0,neural_step=0));(O/Path(__file__).name).write_bytes(Path(__file__).read_bytes());print('verified saved arrays and parameter ledger')
if __name__=='__main__':main()
